"""
Hospital Triage System using Max-Heap.

This module simulates a hospital triage queue where patients with
higher pain levels are prioritized for treatment.

The implementation uses Python's heapq module, which is naturally
a Min-Heap. To simulate a Max-Heap, negative priority values are used.

Complexities:
    - Insert patient: O(log N)
    - Attend patient: O(log N)
    - Update priority: O(N)
"""

import heapq
from typing import List, Tuple


class Patient:
    """
    Represents a patient in the triage system.

    Attributes:
        name (str): Patient name.
        pain_level (int): Pain severity from 1 to 10.
    """

    def __init__(self, name: str, pain_level: int) -> None:
        """
        Initialize a patient.

        Args:
            name (str): Patient name.
            pain_level (int): Pain severity level.
        """
        self.name = name
        self.pain_level = pain_level

    def __repr__(self) -> str:
        """
        Return string representation of the patient.

        Returns:
            str: Formatted patient information.
        """
        return f"{self.name} (Pain Level: {self.pain_level})"


class HospitalTriage:
    """
    Hospital triage queue based on Max-Heap priority management.
    """

    def __init__(self) -> None:
        """
        Initialize an empty triage queue.
        """
        self.heap: List[Tuple[int, Patient]] = []

    def add_patient(self, name: str, pain_level: int) -> None:
        """
        Add a patient to the priority queue.

        Args:
            name (str): Patient name.
            pain_level (int): Pain severity level.

        Complexity:
            O(log N)
        """
        patient = Patient(name, pain_level)

        # Negative value simulates Max-Heap behavior.
        heapq.heappush(self.heap, (-pain_level, patient))

        print(f"Patient '{name}' added with priority {pain_level}.")

    def attend_patient(self) -> None:
        """
        Process the patient with highest priority.

        Complexity:
            O(log N)
        """
        if not self.heap:
            print("No patients in queue.")
            return

        _, patient = heapq.heappop(self.heap)

        print(f"Attending patient: {patient}")

    def show_queue(self) -> None:
        """
        Display the current patient queue.
        """
        if not self.heap:
            print("Queue is empty.")
            return

        print("\nCurrent Queue:")

        for _, patient in sorted(self.heap):
            print(f"- {patient.name}: Pain Level {patient.pain_level}")

    def update_priority(self, name: str, new_pain_level: int) -> None:
        """
        Update the priority of an existing patient.

        This operation simulates Increase Key / Decrease Key.

        Args:
            name (str): Patient name.
            new_pain_level (int): Updated pain level.

        Complexity:
            O(N)
        """
        found = False

        for index, (_, patient) in enumerate(self.heap):
            if patient.name == name:
                found = True

                # Remove old entry.
                self.heap[index] = self.heap[-1]
                self.heap.pop()

                # Rebuild heap structure.
                heapq.heapify(self.heap)

                # Update priority.
                patient.pain_level = new_pain_level

                # Reinsert patient.
                heapq.heappush(
                    self.heap,
                    (-new_pain_level, patient)
                )

                print(
                    f"Priority updated for '{name}' "
                    f"to {new_pain_level}."
                )

                break

        if not found:
            print(f"Patient '{name}' not found.")


def main() -> None:
    """
    Execute triage simulation.
    """
    triage = HospitalTriage()

    # Add patients.
    triage.add_patient("John", 4)
    triage.add_patient("Maria", 9)
    triage.add_patient("Carlos", 6)
    triage.add_patient("Anna", 2)

    triage.show_queue()

    # Attend highest priority patient.
    triage.attend_patient()

    # Increase priority.
    triage.update_priority("John", 10)

    triage.show_queue()

    # Attend next patient.
    triage.attend_patient()


if __name__ == "__main__":
    main()